SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age 
FROM singer 
WHERE Country = 'France';

SELECT AVG(Age) AS Average_Age, MIN(Age) AS Minimum_Age, MAX(Age) AS Maximum_Age 
FROM singer 
WHERE Country = 'France';

SELECT singer.Country, COUNT(singer.Singer_ID) AS Number_of_Singers
FROM singer
GROUP BY singer.Country;

SELECT Country, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Country;

SELECT T1.Name AS Stadium_Name, T1.Capacity AS Stadium_Capacity 
FROM stadium AS T1 
WHERE T1.Average = (SELECT MAX(Average) FROM stadium);

SELECT DISTINCT T1.Name 
FROM stadium AS T1 
WHERE NOT EXISTS (
    SELECT 1 FROM concert AS T2 
    WHERE T2.Stadium_ID = T1.Stadium_ID
);

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS AvgCapacity FROM stadium GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity > T2.AvgCapacity;

SELECT singer.Name 
FROM singer 
WHERE singer.Age > 25 AND singer.Is_male = 1;

SELECT COUNT(CASE WHEN Is_male = 'Male' THEN Singer_ID ELSE NULL END) AS Male_Singers,
       COUNT(CASE WHEN Is_male = 'Female' THEN Singer_ID ELSE NULL END) AS Female_Singers 
FROM singer;

SELECT T1.Name 
FROM singer AS T1 
WHERE T1.Age = (SELECT MIN(Age) FROM singer);

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS Avg_Avg FROM stadium GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity > T2.Avg_Avg;

SELECT T1.Name FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS Avg_Avg FROM stadium GROUP BY Stadium_ID
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID WHERE T1.Capacity < T2.Avg_Avg;

SELECT T1.Name AS Singer_Name, T2.concert_Name AS Concert_Name, T2.Year AS Concert_Year 
FROM singer_in_concert AS T1 
JOIN concert AS T2 ON T1.concert_ID = T2.concert_ID;

SELECT DISTINCT T1.Stadium_ID, COUNT(DISTINCT T2.concert_ID) AS Number_of_Concerts_Held 
FROM stadium AS T1 
JOIN concert AS T2 ON T1.Stadium_ID = T2.Stadium_ID;
